const owner = 'hsndm566';
const repo = 'hsndm.tech';
const branch = 'main';
// Each file seeded from the ACTUAL Claude/Opus draft commit (design to finish)
// plus the current working file on main (functionality to preserve).
const files = [
  { filePath: 'index.html',     claudeSha: '8d22d8b' },
  { filePath: 'dashboard.html', claudeSha: '9f17a4c' },
  { filePath: 'cv.html',        claudeSha: '1e1382b' },
];
return files.map(f => ({ json: { owner, repo, branch, filePath: f.filePath, claudeSha: f.claudeSha } }));

const meta = $('Loop Over Files').first().json;

// Claude's draft (text response body).
const draftResp = $('Fetch Claude Draft').item.json;
let claudeDraft = draftResp.data;
if (typeof claudeDraft !== 'string') { claudeDraft = (draftResp.body || draftResp.text || '') + ''; }

// Working file (base64 from GitHub).
const wResp = $('Fetch Working File').item.json;
const raw = wResp.content || '';
let working;
if ((wResp.encoding || 'base64') === 'base64') { try { working = Buffer.from(raw, 'base64').toString('utf8'); } catch (e) { working = raw; } }
else { working = raw; }

// Tokens the finished file MUST still contain (extracted from the WORKING file).
const preserve = [];
const urls = working.match(/https?:\/\/[^\s"'<>]+/g) || [];
for (const u of urls) { if (u.indexOf('app.n8n.cloud/webhook') !== -1 && preserve.indexOf(u) === -1) preserve.push(u); }
const sid = working.match(/SHEET_ID\s*=\s*["']([^"']+)["']/);
if (sid) preserve.push(sid[1]);

const systemPrompt = [
  'You are a world-class front-end engineer completing an unfinished web page. You are given TWO inputs:',
  '1) DRAFT: an incomplete / truncated HTML file that defines the INTENDED visual design (premium dark glassmorphism, accent color #2563eb, frosted translucent cards with backdrop-filter blur, gradients, soft shadows, strong hierarchy, mobile responsive). This is the creative direction you must adopt and FINISH.',
  '2) WORKING: the current complete, fully-functional version of the same page.',
  '',
  'Your task: produce ONE complete, valid HTML file that adopts the DRAFT visual design and finishes it properly (complete every truncated section, close every tag), while preserving EVERY piece of functionality from WORKING.',
  'You MUST keep working and verbatim: all <script> logic, the Google Sheets SHEET_ID and the gviz fetch, any Chart.js charts, all form field name and id attributes, all webhook and API endpoint URLs, the Julie chatbot, and the Google Translate widget.',
  'Do NOT drop any feature that exists in WORKING. Do NOT change any element id or name attribute referenced by scripts, and do NOT change any endpoint URL or SHEET_ID value.',
  'Output ONLY the complete HTML file, starting with <!DOCTYPE html> and ending with </html>. No markdown fences, no preamble, no commentary.',
].join('\n');

const userContent = '=== DRAFT (Claude/Opus design direction to FINISH) ===\n' + claudeDraft + '\n\n=== WORKING (functionality to PRESERVE) ===\n' + working;

return [{ json: {
  owner: meta.owner, repo: meta.repo, branch: meta.branch, filePath: meta.filePath,
  systemPrompt, userContent, preserve, workingLen: working.length, draftLen: (claudeDraft || '').length,
} }];

const d = $('Assemble Prompt').item.json;
const resp = $input.first().json;
let content = '';
try { content = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || ''; } catch (e) { content = ''; }
content = (content || '').trim();
if (content.indexOf('\u0060\u0060\u0060') === 0) { content = content.replace(/^\u0060\u0060\u0060[a-zA-Z]*\n?/, '').replace(/\u0060\u0060\u0060\s*$/, '').trim(); }
const di = content.indexOf('<!DOCTYPE html>');
const hi = content.lastIndexOf('</html>');
const di2 = di === -1 ? 0 : di;
if (hi !== -1) content = content.substring(di2, hi + 7).trim();
const startsOk = content.indexOf('<!DOCTYPE html>') === 0;
const endsOk = content.slice(-7) === '</html>';
const bodyOpen = (content.match(/<body[\s>]/gi) || []).length;
const bodyClose = (content.match(/<\/body>/gi) || []).length;
const scriptOpen = (content.match(/<script[\s>]/gi) || []).length;
const scriptClose = (content.match(/<\/script>/gi) || []).length;
const preserve = d.preserve || [];
const missing = [];
for (const t of preserve) { if (content.indexOf(t) === -1) missing.push(t); }
const themeOk = content.indexOf('#2563eb') !== -1 && /backdrop-filter/i.test(content);
const lenOk = content.length >= Math.floor((d.workingLen || 0) * 0.5);
const structOk = startsOk && endsOk && bodyOpen >= 1 && bodyOpen === bodyClose && scriptOpen >= 1 && scriptOpen === scriptClose;
const isValid = structOk && missing.length === 0 && themeOk && lenOk;
const reason = 'ZAI start=' + startsOk + ' end=' + endsOk + ' body=' + bodyOpen + '/' + bodyClose + ' script=' + scriptOpen + '/' + scriptClose + ' theme=' + themeOk + ' lenOk=' + lenOk + ' missing=' + missing.length + ' len=' + content.length;
return [{ json: { owner: d.owner, repo: d.repo, branch: d.branch, filePath: d.filePath, finalHtml: content, isValid, reason, provider: 'ZAI' } }];

